def is_sum_free(s):
    s_set = set(s)
    for x in s:
        for y in s:
            if x + y in s_set:
                return False
    return True

from itertools import product

def can_partition(n, m):
    # Try all partitions of {1, ..., n} into m sets
    # A partition can be represented as a tuple of length n, where each element is in {0, ..., m-1}
    for p in product(range(m), repeat=n):
        sets = [[] for _ in range(m)]
        for i, color in enumerate(p):
            sets[color].append(i + 1)

        if all(is_sum_free(s) for s in sets):
            return True
    return False

for n in range(1, 16):
    print(f"n={n}, m=2: {can_partition(n, 2)}")
    print(f"n={n}, m=3: {can_partition(n, 3)}")
